-- ============================================================
-- STEP 1b: Grant precise SELECT-only permissions to theme_analyst
-- ============================================================

-- First, revoke any existing broad privileges to start clean
REVOKE ALL PRIVILEGES ON ALL TABLES IN SCHEMA public FROM theme_analyst;

-- Grant SELECT on reference tables (read-only, full access)
GRANT SELECT ON lego_themes         TO theme_analyst;
GRANT SELECT ON lego_colors         TO theme_analyst;
GRANT SELECT ON lego_parts          TO theme_analyst;
GRANT SELECT ON lego_part_categories TO theme_analyst;

-- Grant SELECT on main data tables (RLS will further restrict rows)
GRANT SELECT ON lego_sets            TO theme_analyst;
GRANT SELECT ON lego_inventories     TO theme_analyst;
GRANT SELECT ON lego_inventory_parts TO theme_analyst;

-- Explicitly deny write operations (belt-and-suspenders)
REVOKE INSERT, UPDATE, DELETE ON lego_themes          FROM theme_analyst;
REVOKE INSERT, UPDATE, DELETE ON lego_colors          FROM theme_analyst;
REVOKE INSERT, UPDATE, DELETE ON lego_parts           FROM theme_analyst;
REVOKE INSERT, UPDATE, DELETE ON lego_part_categories FROM theme_analyst;
REVOKE INSERT, UPDATE, DELETE ON lego_sets            FROM theme_analyst;
REVOKE INSERT, UPDATE, DELETE ON lego_inventories     FROM theme_analyst;
REVOKE INSERT, UPDATE, DELETE ON lego_inventory_parts FROM theme_analyst;
"}

